window.OVA_CONTENT={"slug":"seccion-02-herencia-y-mejoramiento","title":"Herencia y mejoramiento agroindustrial","minutes":40,"summary":"Interpreta segregación, variación y selección sin reducir los caracteres productivos a modelos demasiado simples.","objective":"Aplicar principios de herencia al análisis responsable del mejoramiento vegetal y animal.","stages":[{"eyebrow":"Fundamento","title":"1. Alelos y segregación","reading":"En un modelo mendeliano, un individuo posee dos alelos para un gen y estos se separan durante la formación de gametos. La descendencia recibe una copia de cada progenitor.","application":"El modelo ayuda a anticipar proporciones, siempre que el rasgo estudiado se ajuste a sus supuestos.","activity":{"type":"choice","question":"¿Qué expresa la segregación?","options":["La separación de alelos al formarse los gametos","La desaparición del alelo recesivo","La copia idéntica de todos los descendientes"],"answer":[0],"success":"Los alelos se separan y vuelven a combinarse."}},{"eyebrow":"Lenguaje genético","title":"2. Genotipo no es fenotipo","reading":"El genotipo describe la composición genética; el fenotipo corresponde a características observables producidas por genes y ambiente. Un alelo dominante se expresa en heterocigosis, pero dominante no significa mejor ni más frecuente.","application":"Este lenguaje permite leer reportes de cruzamientos sin convertir una relación genética en un juicio de valor.","activity":{"type":"match","question":"Relaciona cada término con su significado.","pairs":[{"label":"Genotipo","value":"composicion","option":"Composición de alelos"},{"label":"Fenotipo","value":"observable","option":"Característica observable"},{"label":"Heterocigoto","value":"diferentes","option":"Dos alelos diferentes"}],"answer":["composicion","observable","diferentes"],"success":"Cada término responde una pregunta distinta."}},{"eyebrow":"Complejidad","title":"3. Rasgos productivos complejos","reading":"Rendimiento, crecimiento, eficiencia alimenticia o tolerancia al estrés suelen depender de múltiples genes y del ambiente. Por ello, una proporción mendeliana simple rara vez explica por sí sola el desempeño productivo.","application":"Los programas de mejoramiento combinan registros, evaluación de familias, condiciones de prueba y objetivos definidos.","activity":{"type":"multi","question":"¿Qué variables deben acompañar la información genética?","options":["Ambiente de evaluación","Manejo productivo","Registros de desempeño","Color del formato administrativo"],"answer":[0,1,2],"success":"La evidencia productiva complementa la herencia."}},{"eyebrow":"Selección","title":"4. Decidir qué mejorar","reading":"La selección debe partir de un objetivo verificable y considerar variación disponible, medición del rasgo, reproducción y evaluación de resultados. Elegir sin criterios puede reducir diversidad o desplazar características útiles.","application":"La organización debe equilibrar productividad, adaptación, calidad, costos y conservación de recursos genéticos.","activity":{"type":"order","question":"Ordena un ciclo básico de mejoramiento.","items":["Definir el objetivo","Medir variación","Seleccionar progenitores","Evaluar descendencia","Revisar resultados y diversidad"],"answer":[0,1,2,3,4],"success":"El mejoramiento es un proceso evaluado, no una compra aislada."}},{"eyebrow":"Caso aplicado","title":"5. Material vegetal para una región cálida","reading":"Un proveedor ofrece una variedad de alto rendimiento probada en clima templado. La empresa opera bajo alta temperatura y disponibilidad irregular de agua.","application":"Antes de adquirirla conviene revisar evidencia en ambientes comparables, adaptación, calidad del producto y riesgo productivo.","activity":{"type":"choice","question":"¿Cuál decisión está mejor sustentada?","options":["Realizar una prueba controlada local y comparar indicadores","Comprar todo el material por su rendimiento máximo","Rechazar cualquier variedad mejorada"],"answer":[0],"success":"La adaptación debe comprobarse en el contexto de uso."}}],"number":"02","references":["Audesirk, T. et al. (2017). Biología: La vida en la tierra con fisiología. Pearson Educación.","Freeman, S. (2009). Biología. Pearson Educación.","Gutiérrez Ramírez, L. A. (2016). Los microorganismos en la agroindustria. Editorial Lasallista.","Mader, S. S. (2024). Biología. McGraw-Hill.","Velázquez Ocampo, M. P. (2020). Biología II. Cengage Learning."]};